-- composition of rule kernels L:replace_distinct_aggregate x L:simplify_expressions (datafusion), template cte_twice
WITH ka AS (SELECT TRUE AS c0, 1.5::numeric AS c1), kb AS (SELECT '2000-01-01'::date AS c0, 'NaN'::text AS c1 UNION SELECT '1999-12-31'::date AS c0, 'abc'::text AS c1) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT TRUE AS c0, 1.5::numeric AS c1) AS ka) + (SELECT count(*) FROM (SELECT '2000-01-01'::date AS c0, 'NaN'::text AS c1 UNION SELECT '1999-12-31'::date AS c0, 'abc'::text AS c1) AS kb)
